// write via label
const writeRoot = page.frameLocator("iframe#billing-split-frame").getByRole("form", { name: "Embedded split composer" })
const writeTarget = writeRoot.getByLabel("Draft note")
await expect(writeTarget).toBeVisible()
await expect(writeTarget).toBeEditable()
await expect(writeTarget).toHaveValue("Need billing follow-up")
await writeTarget.fill(INPUT_TEXT)

// submit via role
const submitRoot = page.frameLocator("iframe#billing-split-frame").getByRole("form", { name: "Embedded split composer" })
const submitTarget = submitRoot.getByRole("button", { name: "Queue follow-up" })
await expect(submitTarget).toBeVisible()
await expect(submitTarget).toBeEnabled()
await submitTarget.click()

// read via text
const readTarget = page.getByText("Top-level billing summary is current")
await expect(readTarget).toBeVisible()
await expect(readTarget).toContainText("Top-level billing summary is current")
const readText = await readTarget.innerText()
